#!/usr/bin/env python3
"""Run all required ping tests from hosts."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

HOSTS = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}

NON_GUEST = ["B1-PC1","B1-PC2","B2-PC1","B2-PC2","B3-PC1","B3-PC2","B4-PC1","B4-PC2"]
GUEST = ["B4-PC3","B4-PC4"]
INTERNET = ["8.8.8.8", "1.1.1.1"]

def ping_from(src_name, targets):
    mgmt_ip = HOSTS[src_name][0]
    dev = ConnectHandler(device_type="linux", host=mgmt_ip, username="root", password="alpine", timeout=30)
    results = {}
    for tgt_name, tgt_ip in targets:
        out = dev.send_command(f"ping -c 2 -W 3 {tgt_ip}", read_timeout=15)
        ok = "0% packet loss" in out or "1 packets received" in out or "2 packets received" in out
        results[(src_name, tgt_name, tgt_ip)] = ok
    dev.disconnect()
    return results

# Build test matrix
all_tests = {}
for src in NON_GUEST + GUEST:
    targets = []
    # Internet targets
    for ip in INTERNET:
        targets.append((ip, ip))
    # Other hosts
    for dst in NON_GUEST + GUEST:
        if dst != src:
            targets.append((dst, HOSTS[dst][1]))
    all_tests[src] = targets

all_results = {}
with ThreadPoolExecutor(max_workers=10) as ex:
    futs = {ex.submit(ping_from, src, tgts): src for src, tgts in all_tests.items()}
    for f in as_completed(futs):
        all_results.update(f.result())

# Report
print("=== Non-guest to Non-guest (should PASS) ===")
ng_pass = 0
ng_fail = 0
for src in NON_GUEST:
    for dst in NON_GUEST:
        if dst != src:
            key = (src, dst, HOSTS[dst][1])
            ok = all_results.get(key)
            if ok:
                ng_pass += 1
            else:
                ng_fail += 1
                print(f"  FAIL: {src} -> {dst} ({HOSTS[dst][1]})")
print(f"  {ng_pass} pass, {ng_fail} fail\n")

print("=== Guest to Guest (should PASS) ===")
for src in GUEST:
    for dst in GUEST:
        if dst != src:
            key = (src, dst, HOSTS[dst][1])
            ok = all_results.get(key)
            print(f"  {'PASS' if ok else 'FAIL'}: {src} -> {dst}")

print("\n=== Guest <-> Non-guest (should FAIL = policy working) ===")
policy_ok = 0
policy_bad = 0
for src in GUEST:
    for dst in NON_GUEST:
        key = (src, dst, HOSTS[dst][1])
        ok = all_results.get(key)
        if not ok:
            policy_ok += 1
        else:
            policy_bad += 1
            print(f"  POLICY VIOLATION: {src} -> {dst} reachable!")
for src in NON_GUEST:
    for dst in GUEST:
        key = (src, dst, HOSTS[dst][1])
        ok = all_results.get(key)
        if not ok:
            policy_ok += 1
        else:
            policy_bad += 1
            print(f"  POLICY VIOLATION: {src} -> {dst} reachable!")
print(f"  {policy_ok} correctly blocked, {policy_bad} policy violations\n")

print("=== Internet reachability (should PASS) ===")
for src in NON_GUEST + GUEST:
    for ip in INTERNET:
        key = (src, ip, ip)
        ok = all_results.get(key)
        if not ok:
            print(f"  FAIL: {src} -> {ip}")
        else:
            print(f"  PASS: {src} -> {ip}")
